CREATE proc [dbo].[uspKotDeptWiseLess] @OrderKey nvarchar(50) as  select d.department_name,ok.LessReason as category_name,ok.ItemId,i.item_name,ok.ItemComment, i.sale_price,ok.OrderKey,sum(ok.Qty) as Qty,ok.KotStatus,ok.Comments,p.printer, (sum(ok.Qty) * (de.qty)) as DealQty,de.Item_name as DealItem, (select department from CategoryPos  where category_name = (select category_name from ItemPos where item_name = de.Item_name)) as DealDepartment, (select printer from Printer_setup  where department = (select department from CategoryPos where category_name =  (select category_name from ItemPos where item_name = de.Item_name))) as DealPrinter  from DepartmentPOS d inner join CategoryPOS c on d.Department_Name = c.Department  left join Printer_Setup p on p.department = d.Department_Name  inner join ItemPOS i on i.Category_Name = c.Category_Name  left join Deals de on i.Item_name = de.Deal_Name  inner join OrderKot ok on i.Id = ok.ItemId   where ok.OrderKey = @OrderKey and KotStatus <> 1 and p.[document] = 'KOT (Department)'  and ok.Comments = 'LESS' and i.Category_name <>'DealsOnSpot' group by d.department_name,ok.LessReason,ok.ItemId,i.item_name,ok.ItemComment,i.sale_price,ok.OrderKey,ok.KotStatus, ok.Comments,p.printer  ,de.Item_name,de.qty  order by d.department_name     select *,'Dpt' as Dpt from dine_in_order di  inner join Shift_Opening so on di.z_number = so.z_report_number  where di.order_key = @OrderKey 